function Profiles:GetAccount()local p=HolyStorm.Data.PlayerStore:Get(HolyStorm.Data.PlayerStore:GetLocalPlayerId());p.metadata=type(p.metadata)=="table"and p.metadata or {};return p end
function Profiles:Select(guid)self.selected=guid;local p=self:GetAccount();local c=HolyStorm.Data.CharacterStore:Get(guid);local cp=c and c.profile or {};for i,x in ipairs(fields)do self.edits[i]:SetText(i<=3 and(p.metadata[x[1]]or"")or(cp[x[1]]or""))end end
