function Profiles:CycleCharacter()local list={};for guid in pairs(self:GetAccount().characters or{})do list[#list+1]=guid end;table.sort(list);for i,guid in ipairs(list)do if guid==self.selected then self:Select(list[i%#list+1]);return end end;if list[1]then self:Select(list[1])end end
